// <auto-generated/>
using CodeBeam.UltimateAuth.Client;
using CodeBeam.UltimateAuth.Core.Domain;
using CodeBeam.UltimateAuth.IdentityLab.Contracts;
using Microsoft.AspNetCore.Components;
using MudBlazor;

#nullable enable

namespace CodeBeam.UltimateAuth.IdentityLab.Components.Layout;

public partial class DashboardLayout
{
    [CascadingParameter]
    private UAuthState? AuthState { get; set; }

    private string UserName => AuthState?.Identity?.PrimaryUserName ?? "User";
    private string DisplayName => UserName;
    private string AvatarInitials => GetInitials(DisplayName);
    private LabDashboardSnapshot? _sandbox;
    private UserKey? _loadedUserKey;
    private bool _drawerOpen = true;
    private bool _authOperationBusy;

    private string UltimateAuthVersion => ProductInfoProvider.Get().DisplayVersion;

    private bool ShowManagement =>
        AuthState?.IsInRole(LabRoles.Admin) == true ||
        (AuthState?.IsInRole(LabRoles.Owner) == true &&
         _sandbox?.IsOwner == true);

    protected override void OnInitialized()
    {
        DarkModeManager.Changed += OnThemeChanged;
    }

    protected override async Task OnParametersSetAsync()
    {
        var userKey = AuthState?.Identity?.UserKey;

        if (userKey is null)
        {
            _sandbox = null;
            _loadedUserKey = null;
            return;
        }

        if (_loadedUserKey == userKey)
            return;

        _loadedUserKey = userKey;

        _sandbox = await DashboardService.GetAsync(userKey.Value);
    }

    private async Task ValidateSessionAsync()
    {
        if (_authOperationBusy)
            return;

        _authOperationBusy = true;

        try
        {
            var result = await UAuthClient.Flows.ValidateAsync();

            if (result.IsValid)
            {
                Snackbar.Add("Your current session is valid.", Severity.Success);
                return;
            }

            var message = result.State switch
            {
                SessionState.Expired => "Your session has expired. Please sign in again.",
                SessionState.DeviceMismatch => "This session is not valid for the current device.",

                _ => $"Session validation returned: {result.State}"
            };

            Snackbar.Add(message, Severity.Warning);
        }
        catch (Exception)
        {
            Snackbar.Add("Unable to validate the session. Please try again.", Severity.Error);
        }
        finally
        {
            _authOperationBusy = false;
        }
    }

    private async Task RefreshSessionAsync()
    {
        if (_authOperationBusy)
            return;

        _authOperationBusy = true;

        try
        {
            await UAuthClient.Flows.RefreshAsync(false);
            Snackbar.Add("Refresh request completed.", Severity.Success);
        }
        catch (Exception)
        {
            Snackbar.Add("Unable to refresh the session.", Severity.Error);
        }
        finally
        {
            _authOperationBusy = false;
        }
    }

    private void OnThemeChanged()
    {
        _ = InvokeAsync(StateHasChanged);
    }

    private async Task LogoutAsync()
    {
        await UAuthClient.Flows.LogoutAsync();
    }

    public void Dispose()
    {
        DarkModeManager.Changed -= OnThemeChanged;
    }

    private static string GetInitials(string? displayName)
    {
        if (string.IsNullOrWhiteSpace(displayName))
            return "?";

        var parts = displayName.Trim()
            .Split(' ', StringSplitOptions.RemoveEmptyEntries);

        var initials = parts.Length > 1
            ? $"{parts[0][0]}{parts[^1][0]}"
            : new string(parts[0].Take(2).ToArray());

        return initials.ToUpperInvariant();
    }
}
